  staff: [800, 80],
  potion: [400, 40],
};

const COMPONENTS = ['rune', 'moonstone'];

/** Base premium for a building block of exactly 3 alike components. */
export const BLOCK_SIZE = 3;
export const BLOCK_PREMIUM = 60;

